package com.fooddelivery.mail.service;import com.fooddelivery.mail.entity.MailDelivery;import com.fooddelivery.mail.repository.MailDeliveryRepository;import org.springframework.mail.SimpleMailMessage;import org.springframework.mail.javamail.JavaMailSender;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class MailService{private final JavaMailSender sender;private final MailDeliveryRepository repository;private final String from;public MailService(JavaMailSender s,MailDeliveryRepository r,@Value("${app.mail.from:no-reply@example.com}")String f){sender=s;repository=r;from=f;}
 @Transactional(noRollbackFor=MailDeliveryFailureException.class) public MailDelivery send(String to,String subject,String body){try{SimpleMailMessage m=new SimpleMailMessage();m.setFrom(from);m.setTo(to);m.setSubject(subject);m.setText(body);sender.send(m);return repository.save(new MailDelivery(to,subject,"SENT",null));}catch(Exception e){String msg=e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();repository.save(new MailDelivery(to,subject,"FAILED",msg.substring(0,Math.min(1000,msg.length()))));throw new MailDeliveryFailureException("Mail delivery failed",e);}}
 public static class MailDeliveryFailureException extends RuntimeException{public MailDeliveryFailureException(String message,Throwable cause){super(message,cause);}}
 public record MailRequest(String to,String subject,String body){}
}
